import React, { useCallback, useEffect, useLayoutEffect, useRef } from "react";
import {
  motion,
  useMotionValue,
  useMotionValueEvent,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
} from "framer-motion";
import "./ScrollSequenceMotion.css";

const INITIAL_BUFFER = 16;
const MAX_CONCURRENT = 8;
const LOOKAHEAD = 40;

function resolveAssetBase(folderPath) {
  const trimmed = folderPath.trim();
  const envBase =
    typeof process.env.PUBLIC_URL === "string"
      ? process.env.PUBLIC_URL.replace(/\/$/, "")
      : "";

  if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) {
    return trimmed.endsWith("/") ? trimmed : `${trimmed}/`;
  }

  let relative = trimmed.startsWith("/") ? trimmed.slice(1) : trimmed;

  let base = envBase !== "" ? `${envBase}/${relative}` : `/${relative}`;

  if (
    typeof window !== "undefined" &&
    window.location?.pathname &&
    envBase === ""
  ) {
    const segments = window.location.pathname.split("/").filter(Boolean);
    const first = segments[0];
    const needsRepoPrefix =
      first && base.startsWith("/sequences") && !base.startsWith(`/${first}/`);

    if (needsRepoPrefix) {
      base = `/${first}${base}`;
    }
  }

  return base.endsWith("/") ? base : `${base}/`;
}

/**
 * Single file from `public/` (e.g. place `affiliates.mp4` in `public/` → URL `/affiliates.mp4`).
 * Optional GitHub Pages-style path prefix matches `resolveAssetBase` for sequences.
 */
function resolvePublicMediaPath(fileName) {
  const file = fileName.replace(/^\//, "");
  const envBase =
    typeof process.env.PUBLIC_URL === "string"
      ? process.env.PUBLIC_URL.replace(/\/$/, "")
      : "";
  let path = envBase !== "" ? `${envBase}/${file}` : `/${file}`;

  if (
    typeof window !== "undefined" &&
    window.location?.pathname &&
    envBase === ""
  ) {
    const segments = window.location.pathname.split("/").filter(Boolean);
    const first = segments[0];
    const needsRepoPrefix =
      first &&
      (path.startsWith("/sequences") || path.startsWith("/affiliates")) &&
      !path.startsWith(`/${first}/`);

    if (needsRepoPrefix) {
      path = `/${first}${path}`;
    }
  }

  return path;
}

function isDrawable(img) {
  return img && img.complete && img.naturalWidth > 0;
}

function findDrawableFrameIndex(images, targetIndex) {
  for (let i = targetIndex; i >= 0; i--) {
    if (isDrawable(images[i])) return i;
  }
  return -1;
}

function measureEndScrollY(endSelector) {
  const maxY = Math.max(
    1,
    document.documentElement.scrollHeight - window.innerHeight
  );
  if (!endSelector) return maxY;
  const el = document.querySelector(endSelector);
  if (!el) return maxY;
  const top = el.getBoundingClientRect().top + window.scrollY;
  return Math.max(1, Math.min(top, maxY));
}

/** Default narrative (previously in Hero / About / Quote / Cta). */
const defaultScrollTextSections = [
  {
    id: "hero",
    from: 0,
    to: 0.1,
    title: "SERVEDNET.GG",
  },
  {
    id: "about",
    from: 0.15,
    to: 0.25,
    body: "We curate our network with the same thorough standards you apply to your brand.",
  },
  {
    id: "quote",
    from: 0.3,
    to: 0.4,
    body: "A closed ecosystem of the industry's highest-performing talent.",
  },

  {
    id: "cta-elevation",
    from: 0.45,
    to: 0.55,
    body: "True elevation is never crowded.",
  },
  {
    id: "cta-interest",
    from: 0.6,
    to: 0.95,
    title: "Interested?",
  },
  /*
  {
    id: "affiliates",
    from: 0.99,
    to: 1.1,
    videoSrc: resolvePublicMediaPath("affiliates.mp4"),
    videoLabel: "Affiliates",
  },
  */
];

function NarrativeBlock({ progress, section }) {
  const { from, to, title, body, videoSrc, videoLabel } = section;
  const pad = 0.06;
  const opacity = useTransform(
    progress,
    [Math.max(0, from - pad), from, to, Math.min(1, to + pad)],
    [0, 1, 1, 0]
  );
  const videoRef = useRef(null);

  const syncVideoPlayback = useCallback(
    (p) => {
      const el = videoRef.current;
      if (!el || !videoSrc) return;
      const inRange = p >= from && p <= to;
      if (inRange) {
        el.play().catch(() => {});
      } else {
        el.pause();
      }
    },
    [from, to, videoSrc]
  );

  useLayoutEffect(() => {
    syncVideoPlayback(progress.get());
  }, [progress, syncVideoPlayback]);

  useMotionValueEvent(progress, "change", syncVideoPlayback);

  const blockClass =
    videoSrc != null && videoSrc !== ""
      ? "ScrollSequenceMotion-textBlock ScrollSequenceMotion-mediaBlock"
      : "ScrollSequenceMotion-textBlock";

  return (
    <motion.div
      className={blockClass}
      style={{
        opacity,
        position: "absolute",
        left: "clamp(1.25rem, 4vw, 3.5rem)",
        right: "clamp(1.25rem, 4vw, 3.5rem)",
        bottom: "clamp(2rem, 8vh, 5rem)",
      }}
    >
      {videoSrc ? (
        <video
          ref={videoRef}
          className="ScrollSequenceMotion-video"
          src={videoSrc}
          muted
          playsInline
          loop
          preload="metadata"
          aria-label={videoLabel || "Video"}
        />
      ) : null}
      {!videoSrc && title ? (
        <h2 className="ScrollSequenceMotion-title">{title}</h2>
      ) : null}
      {!videoSrc && body ? (
        <p className="ScrollSequenceMotion-body">{body}</p>
      ) : null}
    </motion.div>
  );
}

/**
 * Canvas scrubbed PNG sequence driven by document scroll via Framer Motion.
 * Optional `endSelector`: progress 1 when that element's top reaches viewport top (capped at max scroll).
 */
export default function ScrollSequenceMotion({
  frameCount = 600,
  folderPath = "/sequences/anim02/",
  filePrefix = "anim02-",
  fileExtension = "png",
  padLength = 3,
  canvasWidth = 3000,
  canvasHeight = 1500,
  endSelector,
  textSections = defaultScrollTextSections,
}) {
  const canvasRef = useRef(null);
  const endScrollYRef = useRef(1);
  const lastQueuedCenterRef = useRef(-1);
  const reduceMotionRef = useRef(false);
  const reduceMotion = useReducedMotion();
  reduceMotionRef.current = Boolean(reduceMotion);

  const onFrameScrubRef = useRef(() => {});

  const { scrollY } = useScroll();
  const progressMv = useMotionValue(0);
  const frameTarget = useMotionValue(0);

  const smoothedFrame = useSpring(
    frameTarget,
    reduceMotion ? false : { stiffness: 88, damping: 34 }
  );

  const smoothedFrameRef = useRef(smoothedFrame);
  smoothedFrameRef.current = smoothedFrame;

  const syncScrollMapping = useCallback(() => {
    if (reduceMotionRef.current) {
      progressMv.set(1);
      frameTarget.set(frameCount - 1);
      return;
    }
    const end = Math.max(1, endScrollYRef.current);
    const y = typeof window !== "undefined" ? window.scrollY : scrollY.get();
    const p = Math.min(1, Math.max(0, y / end));
    progressMv.set(p);
    frameTarget.set(p * (frameCount - 1));
  }, [frameCount, frameTarget, progressMv, scrollY]);

  useLayoutEffect(() => {
    const updateEnd = () => {
      endScrollYRef.current = measureEndScrollY(endSelector);
      syncScrollMapping();
    };
    updateEnd();
    window.addEventListener("load", updateEnd);
    window.addEventListener("resize", updateEnd);
    const ro =
      typeof ResizeObserver !== "undefined" && document.body
        ? new ResizeObserver(updateEnd)
        : null;
    if (ro) ro.observe(document.body);
    return () => {
      window.removeEventListener("load", updateEnd);
      window.removeEventListener("resize", updateEnd);
      if (ro) ro.disconnect();
    };
  }, [endSelector, syncScrollMapping]);

  useLayoutEffect(() => {
    syncScrollMapping();
  }, [syncScrollMapping]);

  useMotionValueEvent(scrollY, "change", (y) => {
    if (reduceMotionRef.current) return;
    const end = Math.max(1, endScrollYRef.current);
    const p = Math.min(1, Math.max(0, y / end));
    progressMv.set(p);
    frameTarget.set(p * (frameCount - 1));
  });

  useLayoutEffect(() => {
    if (reduceMotion) {
      progressMv.set(1);
      frameTarget.set(frameCount - 1);
    } else {
      syncScrollMapping();
    }
  }, [reduceMotion, frameCount, frameTarget, progressMv, syncScrollMapping]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;

    const context = canvas.getContext("2d");
    const base = resolveAssetBase(folderPath);

    let alive = true;
    const images = [];
    for (let i = 0; i < frameCount; i++) {
      images.push(new Image());
    }

    const queue = [];
    const srcAssigned = new Set();
    let inFlight = 0;

    function removeFromQueue(idx) {
      const pos = queue.indexOf(idx);
      if (pos >= 0) queue.splice(pos, 1);
    }

    function enqueueFrame(i, highPriority) {
      if (i < 0 || i >= frameCount || srcAssigned.has(i)) return;
      if (highPriority) {
        removeFromQueue(i);
        queue.unshift(i);
      } else if (!queue.includes(i)) {
        queue.push(i);
      }
    }

    function drawFromScrub(frameValue) {
      if (!alive) return;
      const target = Math.round(frameValue);
      const drawable = findDrawableFrameIndex(images, target);
      if (drawable < 0) return;
      context.clearRect(0, 0, canvasWidth, canvasHeight);
      context.drawImage(images[drawable], 0, 0, canvasWidth, canvasHeight);
    }

    function beginLoadForIndex(i) {
      srcAssigned.add(i);
      inFlight++;
      const img = images[i];
      const paddedIndex = (i + 1).toString().padStart(padLength, "0");
      const done = () => {
        if (!alive) return;
        inFlight--;
        pump();
        onFrameScrubRef.current(smoothedFrameRef.current.get());
      };
      img.onload = done;
      img.onerror = done;
      img.src = `${base}${filePrefix}${paddedIndex}.${fileExtension}`;
    }

    function pump() {
      if (!alive) return;
      while (inFlight < MAX_CONCURRENT && queue.length > 0) {
        const i = queue.shift();
        if (srcAssigned.has(i)) continue;
        beginLoadForIndex(i);
      }
    }

    onFrameScrubRef.current = (v) => {
      if (!alive) return;
      const tf = Math.round(v);
      if (tf !== lastQueuedCenterRef.current) {
        lastQueuedCenterRef.current = tf;
        for (let d = 0; d <= LOOKAHEAD; d++) {
          enqueueFrame(tf + d, true);
          if (tf - d >= 0) enqueueFrame(tf - d, true);
        }
        pump();
      }
      drawFromScrub(v);
    };

    for (let i = INITIAL_BUFFER - 1; i >= 0; i--) {
      enqueueFrame(i, true);
    }
    for (let i = INITIAL_BUFFER; i < frameCount; i++) {
      enqueueFrame(i, false);
    }
    pump();

    requestAnimationFrame(() => {
      if (alive) onFrameScrubRef.current(smoothedFrameRef.current.get());
    });

    return () => {
      alive = false;
      lastQueuedCenterRef.current = -1;
      onFrameScrubRef.current = () => {};
    };
  }, [
    canvasHeight,
    canvasWidth,
    fileExtension,
    filePrefix,
    folderPath,
    frameCount,
    padLength,
  ]);

  useMotionValueEvent(smoothedFrame, "change", (v) => {
    onFrameScrubRef.current(v);
  });

  return (
    <div className="ScrollSequenceMotion">
      <canvas
        ref={canvasRef}
        width={canvasWidth}
        height={canvasHeight}
        className="ScrollSequenceMotion-canvas"
      />
      <div className="ScrollSequenceMotion-overlay" aria-live="polite">
        {textSections.map((section) => (
          <NarrativeBlock
            key={section.id}
            progress={progressMv}
            section={section}
          />
        ))}
      </div>
    </div>
  );
}
